definition.script:
pipeline {
    agent any

    stages {
        stage('multiple') {
            matrix {
                axes {
                    axis {
                        name 'PLATFORM'
                        values 'linux', 'mac', 'windows'
                    }
                    axis {
                        name 'BROWSER'
                        values 'chrome', 'edge', 'firefox', 'safari'
                    }
                    axis { 
                        name 'ARCHITECTURE' 
                        values '32-bit', '64-bit'
                    }
                }
                excludes {
                    exclude {
                        axis { 
                            name 'PLATFORM' 
                            values 'mac'
                        }
                        axis { 
                            name 'ARCHITECTURE' 
                            values '32-bit' 
                        }
                    }
                    exclude { 
                        axis { 
                            name 'PLATFORM' 
                            values 'linux' 
                        }
                        axis { 
                            name 'BROWSER' 
                            values 'safari' 
                        }
                    }
                }
                stages {
                    stage('build') {
                        steps {
                            echo "Version para le navegador ${BROWSER} en ${PLATFORM} (${ARCHITECTURE})"
                        }
                    }
                }
            }
        }
    }
}
